const $=id=>document.getElementById(id),canvas=$('game'),c=canvas.getContext('2d'),game=new Game();let W=960,H=540,scale=1,cam=0,yoff=0,mode='menu',paused=false,selected=0,unlocked=0,total=0,clock=0,last=performance.now(),messageUntil=0,sound=false,audio;const keys=new Set(),touch={left:false,right:false,jump:false},particles=[];
try{unlocked=Math.min(THEMES.length-1,Math.max(0,Number(progressStore.getItem('nico-unlocked'))||0));total=Math.max(0,Number(progressStore.getItem('nico-coins'))||0)}catch{}
function resize(){const d=Math.min(devicePixelRatio||1,2);canvas.width=innerWidth*d;canvas.height=innerHeight*d;W=Math.max(480,540*innerWidth/innerHeight);H=W*innerHeight/innerWidth;scale=canvas.width/W;yoff=Math.max(0,H*.73-480);if(mode==='playing'&&!paused)$('touch').hidden=!touchVisible()}addEventListener('resize',resize);resize();
function rect(x,y,w,h,r,color){c.fillStyle=color;c.beginPath();c.roundRect(x,y,w,h,r);c.fill()}
function ellipse(x,y,rx,ry,color){c.fillStyle=color;c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fill()}
function path(points,color){c.fillStyle=color;c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fill()}
function line(x,y,x2,y2,color,width=2){c.strokeStyle=color;c.lineWidth=width;c.beginPath();c.moveTo(x,y);c.lineTo(x2,y2);c.stroke()}
function cloud(x,y,s=1){c.save();c.translate(x,y);c.scale(s,s);ellipse(0,0,42,14,'#ffffff87');ellipse(-15,-10,20,20,'#ffffff87');ellipse(13,-15,25,24,'#ffffff87');c.restore()}
function scenery(t){c.fillStyle=t.sky;c.fillRect(0,0,W,H);const grad=c.createLinearGradient(0,0,0,H);grad.addColorStop(0,'#ffffff22');grad.addColorStop(1,'#fff7d366');c.fillStyle=grad;c.fillRect(0,0,W,H);ellipse(W*.8,95+yoff*.25,42,42,t.accent);ellipse(W*.8-11,82+yoff*.25,6,6,'#fff9');for(let i=-1;i<9;i++)cloud(i*210-(cam*.12)%210,90+(i%3)*45+yoff*.2,.7+(i%2)*.25);for(let layer=0;layer<2;layer++){const factor=layer?.3:.15,width=layer?260:340;for(let i=-1;i<W/width+2;i++){const x=i*width-(cam*factor)%width,y=480+yoff;ellipse(x,y+(layer?45:0),width*.75,layer?140:210,layer?t.hill:t.far);if(layer){ellipse(x-15,y-50,5,8,'#ffffff22');ellipse(x+20,y-65,4,6,'#ffffff22')}}}for(let i=0;i<9;i++){const x=(i*171+42-cam*.45)%(W+180);if(x<0)continue;ellipse(x,450+yoff,18,48,'#42876818')}}
function tree(x,y,t,s=1){c.save();c.translate(x,y);c.scale(s,s);c.strokeStyle='#8d7956';c.lineWidth=9;c.beginPath();c.moveTo(0,0);c.quadraticCurveTo(-8,-30,3,-72);c.stroke();for(let k=0;k<7;k++){const a=-Math.PI+k*Math.PI/6,dx=Math.cos(a)*45,dy=Math.sin(a)*30;path([[3,-70],[dx*.55,-88+dy*.3],[dx,-60+dy],[dx*.4,-63+dy*.3]],k%2?t.grass:t.hill)}ellipse(2,-72,7,6,'#c2b877');c.restore()}

function prehistoric(t){const base=480+yoff,x=W*.78-(cam*.08)%W;path([[x-150,base],[x-35,base-190],[x+5,base-205],[x+145,base]],t.far);path([[x-35,base-190],[x-23,base-162],[x-10,base-182],[x+5,base-205]],'#f5e5b380');const d=220-(cam*.22)%600;c.save();c.globalAlpha=.2;ellipse(d,base-60,55,24,t.grass);rect(d+30,base-145,14,90,7,t.grass);ellipse(d+46,base-145,22,12,t.grass);for(const dx of[-30,20])rect(d+dx,base-55,11,55,5,t.grass);path([[d-43,base-65],[d-105,base-54],[d-45,base-44]],t.grass);c.restore()}
function platform(b,t){const x=b.x-cam,y=b.y+yoff;if(x+b.w<-50||x>W+50)return;rect(x,y+5,b.w,b.h,9,t.soil);if(b.ground){c.fillStyle='#0000000b';c.fillRect(x,y+35,b.w,b.h-35);for(let k=18;k<b.w;k+=44){ellipse(x+k,y+47+(k%3)*9,5,3,'#ffffff23');ellipse(x+k+13,y+95,7,4,'#5c4c4919');if(k%2===0){c.strokeStyle='#f3d8ae66';c.lineWidth=2;c.beginPath();c.arc(x+k,y+73,8,0,Math.PI*1.7);c.stroke();ellipse(x+k,y+73,2,2,'#f3d8ae66')}}}else{rect(x+6,y+b.h-4,b.w-12,7,4,'#0002')}rect(x,y,b.w,14,7,t.grass);for(let k=4;k<b.w-4;k+=16)ellipse(x+k,y+10,8,5,t.grass);line(x+8,y+3,x+b.w-8,y+3,'#ffffff40',2)}
function coin(o,t){if(o.taken)return;const x=o.x-cam,y=o.y+yoff+Math.sin(clock*3+o.x)*3;if(x<-20||x>W+20)return;const spin=.35+.65*Math.abs(Math.cos(clock*2.5+o.x*.015));ellipse(x,y,12*spin,13,'#c38e30');ellipse(x,y-2,10*spin,12,'#ffdc77');ellipse(x-2*spin,y-5,3*spin,5,'#fff3bc');line(x,y-7,x,y+4,'#d3a34d',2)}
function nico(x,y,face=1,walk=0,s=1){c.save();c.translate(x,y);c.scale(s*face,s);ellipse(0,45,20,4,'#1a49372b');c.translate(0,Math.sin(walk)*1.5);const step=Math.sin(walk)*4;
 // A rounded tail, small arms and dorsal plates identify our little dinosaur.
 c.fillStyle='#469d75';c.beginPath();c.moveTo(-9,15);c.quadraticCurveTo(-24,34,-39,20);c.quadraticCurveTo(-31,42,-8,35);c.fill();
 for(let i=0;i<4;i++)path([[-16-i*5,27+i*.6],[-21-i*5,19+i*.8],[-23-i*5,29+i*.6]],'#edb25e');
 rect(-12,31+step,14,12,6,'#318269');rect(3,31-step,15,12,6,'#3c9974');rect(-12,8,28,29,12,'#66b982');ellipse(5,23,9,13,'#e2ecc0');
 path([[-17,9],[-24,3],[-16,-1]],'#eab562');path([[-15,-3],[-22,-10],[-12,-14]],'#f2c36d');path([[-10,-16],[-13,-25],[-3,-20]],'#f3c976');
 ellipse(0,-3,20,20,'#76c68d');rect(0,-6,28,21,10,'#83cd95');ellipse(9,9,14,7,'#b4dfad');ellipse(8,-8,5,6,'#fff9e6');ellipse(10,-8,2.4,3.4,'#214b3c');ellipse(10,-10,1,1.3,'#fff');ellipse(23,0,1.6,1.7,'#44866a');line(15,9,22,9,'#44866a',1.5);ellipse(1,3,4,2.5,'#efb987');rect(12,16,10,7,4,'#5eac7d');rect(-12,12,28,6,3,'#ec9a53');path([[-10,15],[-20,20],[-13,24],[-6,17]],'#ec9a53');c.restore()}

function beetle(e,t){if(!e.alive)return;const x=e.x-cam,y=e.y+yoff;if(x<-50||x>W+50)return;ellipse(x+18,y+32,21,4,'#20443422');for(let k=0;k<3;k++){const z=Math.sin(clock*10+k)*2;line(x+6+k*10,y+25,x+3+k*12,y+33+z,'#234d53',3)}ellipse(x+18,y+16,19,15,'#397b89');ellipse(x+15,y+9,12,7,'#5ea8ad');line(x+18,y+2,x+18,y+28,'#266371',2);ellipse(x+8,y+15,3,4,'#fff9db');ellipse(x+8,y+16,1.5,2,'#203c43');ellipse(x+27,y+15,3,4,'#fff9db');ellipse(x+27,y+16,1.5,2,'#203c43')}
function flag(x,active,t){x-=cam;const y=480+yoff;line(x,y,x,y-95,'#5e7766',4);ellipse(x,y-98,5,5,t.accent);path([[x+2,y-93],[x+49,y-82],[x+2,y-65]],active?'#e99058':'#f7f4d9');if(active){c.fillStyle='#fff9df';c.font='bold 18px Trebuchet MS';c.fillText('✓',x+8,y-73)}}
function gate(x,t){x-=cam;const y=480+yoff;rect(x-8,y-118,18,118,8,'#e1bb73');rect(x+60,y-118,18,118,8,'#e1bb73');rect(x-8,y-130,86,24,12,'#ffdf9b');rect(x+11,y-106,48,105,22,'#fff7bf77');ellipse(x+35,y-147,18,18,t.accent);c.fillStyle='#fff8d7';c.font='bold 22px Trebuchet MS';c.textAlign='center';c.fillText('✦',x+35,y-139);c.textAlign='left';for(let i=0;i<5;i++)ellipse(x+35+Math.sin(clock+i)*24,y-45-i*10,2,2,'#fff9d1')}
function world(){const lv=game.level,t=THEMES[lv.index];scenery(t);prehistoric(t);c.save();
 if(lv.index===3){
  for(let i=-1;i<W/145+2;i++){
   const x=i*145-(cam*.24)%145,y=430+yoff;
   path([[x,y],[x-18,y-45],[x+3,y-90],[x+24,y-51],[x+17,y]],'#96f4e977');
   path([[x,y],[x+3,y-90],[x+10,y-42],[x+17,y]],'#5dbddc88');
  }
 }
 if(lv.index===4)for(let i=-1;i<W/195+2;i++)cloud(i*195-(cam*.36)%195,360+yoff+(i%3)*30,1.4);
 for(const b of lv.platforms){if(b.ground)for(let k=100;k<b.w;k+=240){const x=b.x+k-cam;if(x>-80&&x<W+80)tree(x,b.y+yoff,t,.65+(k%2)*.2)}}for(const b of lv.platforms)platform(b,t);for(const b of lv.platforms)if(b.ground)for(let k=30;k<b.w-20;k+=83){const x=b.x+k-cam,y=b.y+yoff;if(x<0||x>W)continue;line(x,y,x+1,y-11,t.grass,2);ellipse(x-3,y-13,4,3,t.accent);ellipse(x+3,y-13,4,3,t.accent);ellipse(x,y-15,3,4,'#f9f4d8')}for(const s of lv.spikes){for(let x=s.x;x<s.x+s.w;x+=17)path([[x-cam,s.y+s.h+yoff],[x+8-cam,s.y+yoff],[x+16-cam,s.y+s.h+yoff]],'#758d91')}for(const o of lv.coins)coin(o,t);
 for(const power of lv.powers){
  if(power.taken)continue;
  const x=power.x-cam,y=power.y+yoff+Math.sin(clock*4+power.x)*4;
  if(x<-25||x>W+25)continue;
  ellipse(x,y,15,15,power.kind==='heart'?'#ef6580':power.kind==='shield'?'#467dd5':'#845cca');
  c.fillStyle='#fff';c.font='bold 17px sans-serif';c.textAlign='center';c.fillText({heart:'♥',shield:'◆',jump:'↑'}[power.kind],x,y+6);c.textAlign='left';
 }for(const e of lv.enemies)beetle(e,t);flag(lv.checkpoint.x,game.checkpoint,t);gate(lv.end+15,t);if(mode==='menu'){nico(W*.73,480+yoff-93,1,clock*3,2.2)}else if(game.invincible<=0||Math.sin(clock*20)>0){const p=game.player;nico(p.x-cam+15,p.y+yoff+1,p.face,Math.abs(p.vx)>15?clock*12:0)}for(const q of particles){ellipse(q.x-cam,q.y+yoff,q.r,q.r,q.color)}c.restore()}
function beep(freq=600){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq*1.3,audio.currentTime+.1);g.gain.setValueAtTime(.045,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.15);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.16)}catch{}}
function notice(text){$('notice').textContent=text;$('notice').classList.add('show');messageUntil=clock+2.5}
function clear(){keys.clear();for(const k of Object.keys(touch))touch[k]=false;document.querySelectorAll('#touch button').forEach(b=>b.classList.remove('held'))}
function touchVisible(){return matchMedia('(pointer:coarse)').matches||innerWidth<750}
function updateWorldButtons(){const node=$('world-buttons');node.replaceChildren();$('adventure-progress').textContent=(unlocked+1)+' de '+THEMES.length+' mundos disponíveis';THEMES.forEach((t,i)=>{const b=document.createElement('button');b.textContent = String(i+1).padStart(2,'0')+' · '+t.name;b.title=t.name;b.setAttribute('aria-label',(i>unlocked?'Bloqueada: ':'Fase ')+(i+1)+' — '+t.name);b.setAttribute('aria-pressed',String(selected===i));b.disabled=i>unlocked;b.onclick=()=>{selected=i;game.start(i);updateWorldButtons()};node.append(b)})}updateWorldButtons();
function start(index=selected,carry=false){clear();game.start(index,{...(carry?{coins:game.coins,deaths:game.deaths}:{}),explore:$('salta-mode').value==='explore'});updatePowerHud();selected=index;mode='playing';paused=false;cam=0;particles.length=0;$('menu').hidden=true;$('overlay').hidden=true;$('hud').hidden=false;$('touch').hidden=!touchVisible();$('route-progress').value=0;$('world').textContent=String(index+1).padStart(2,'0')+' · '+THEMES[index].name.toUpperCase();notice('Segue as moedas. O portal espera por ti!');$('pause').focus()}
function showDialog(tag,title,description,action){clear();$('touch').hidden=true;$('overlay').hidden=false;$('dialog-tag').textContent=tag;$('dialog-title').textContent=title;$('dialog-description').textContent=description;$('continue').textContent=action;$('continue').focus()}
function pause(){if(mode!=='playing')return;paused=!paused;if(paused)showDialog('UMA PAUSA','Um bocadinho de descanso.','O Dino espera por ti. Continua quando quiseres.','CONTINUAR ↗');else{$('overlay').hidden=true;$('touch').hidden=!touchVisible();clear();$('pause').focus()}}
function win(){mode='won';unlocked=Math.min(THEMES.length-1,Math.max(unlocked,game.level.index+1));total=game.coins;try{progressStore.setItem('nico-unlocked',unlocked);progressStore.setItem('nico-coins',total)}catch{}updateWorldButtons();const last=game.level.index===THEMES.length-1;showDialog(last?'AVENTURA COMPLETA':'FASE CONCLUÍDA',last?'Grande salto, Dino!':'O próximo mundo espera.',game.coins+(game.coins===1?' moeda recolhida nesta aventura. ':' moedas recolhidas nesta aventura. ')+(game.deaths?'Tentaste '+(game.deaths+1)+' vezes. Nunca desististe!':'Uma bela viagem!'),last?'VOLTAR AO INÍCIO ↗':'PRÓXIMA FASE ↗');beep(850)}
$('play').onclick=()=>start();$('pause').onclick=pause;$('continue').onclick=()=>{if(mode==='lost'){start(game.level.index);return}if(mode==='won'){if(game.level.index<THEMES.length-1)start(game.level.index+1,true);else home()}else pause()};$('restart').onclick=()=>start(game.level.index);function home(){mode='menu';paused=false;clear();$('overlay').hidden=true;$('menu').hidden=false;$('hud').hidden=true;$('touch').hidden=true;game.start(selected);updateWorldButtons();$('play').focus()}$('home').onclick=home;$('sound').onclick=()=>{sound=!sound;$('sound').textContent='Som '+(sound?'ligado':'desligado');$('sound').setAttribute('aria-pressed',String(sound));beep()};
addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','Space'].includes(e.code)&&mode==='playing')e.preventDefault();if(e.code==='Escape'&&!e.repeat){pause();return}if(mode==='playing'&&!paused)keys.add(e.code);if(e.code==='Tab'&&!$('overlay').hidden){const buttons=[...$('overlay').querySelectorAll('button')];if(e.shiftKey&&document.activeElement===buttons[0]){e.preventDefault();buttons.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===buttons.at(-1)){e.preventDefault();buttons[0].focus()}}});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>{clear();if(mode==='playing'&&!paused)pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){clear();if(mode==='playing'&&!paused)pause()}});
for(const id of ['left','right','jump']){const b=$(id),active=new Set();b.onpointerdown=e=>{if(mode!=='playing'||paused)return;e.preventDefault();active.add(e.pointerId);touch[id]=true;b.classList.add('held');b.setPointerCapture(e.pointerId)};const end=e=>{active.delete(e.pointerId);touch[id]=active.size>0;b.classList.toggle('held',touch[id])};b.onpointerup=b.onpointercancel=b.onlostpointercapture=end}
function updatePowerHud() {
 const hearts=$('dino-hearts');
 hearts.textContent='♥'.repeat(game.hearts)+'♡'.repeat(game.maxHearts-game.hearts);
 hearts.setAttribute('aria-label',game.hearts+' de '+game.maxHearts+' corações');
 $('dino-power').textContent=[game.shield?'◆ Escudo':'',game.jumpPower>0?'↑ '+Math.ceil(game.jumpPower)+' s':''].filter(Boolean).join(' · ');
}
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.1,Math.max(0,(now-last)/1000));last=now;if(document.hidden)return;clock+=dt;if(mode==='playing'&&!paused){const move=Number(keys.has('KeyD')||keys.has('ArrowRight')||touch.right)-Number(keys.has('KeyA')||keys.has('ArrowLeft')||touch.left),jump=keys.has('Space')||keys.has('KeyW')||keys.has('ArrowUp')||touch.jump,run=keys.has('ShiftLeft')||keys.has('ShiftRight');const steps=Math.max(1,Math.ceil(dt*120));for(let i=0;i<steps;i++){game.update(dt/steps,{move,jump,run});for(const e of game.events){if(e.type==='coin'||e.type==='stomp'){beep(e.type==='coin'?730:240);for(let k=0;k<7;k++)particles.push({x:e.x,y:e.y,vx:Math.cos(k)*70,vy:-60-Math.sin(k)*70,r:2+k%2,color:THEMES[game.level.index].accent,life:.45})}if(e.type==='jump')beep(340);if(e.type==='hurt')notice('Perdeste um coração.');
 if(e.type==='power'){notice({heart:'Coração recuperado!',shield:'Escudo contra um impacto!',jump:'Salto duplo durante 16 segundos!'}[e.kind]);beep(820)}
 if(e.type==='shield')notice('O escudo protegeu-te!');
 if(e.type==='lost'){mode='lost';showDialog('SEM CORAÇÕES','Queres tentar outra vez?','Podes repetir a fase ou escolher Exploração no menu.','TENTAR DE NOVO');break}if(e.type==='checkpoint')notice('Bandeira guardada! Recomeças daqui.');if(e.type==='win'){win();break}}if(mode!=='playing')break}cam+=(Math.max(0,Math.min(game.level.length-W,game.player.x-W*.34))-cam)*(1-Math.exp(-dt*8));updatePowerHud();$('route-progress').value=Math.max($('route-progress').value,Math.min(100,Math.floor(100*game.player.x/game.level.end)));$('coin-count').textContent=game.coins+(game.coins===1?' moeda':' moedas');$('checkpoint').textContent=game.checkpoint?'Bandeira guardada ✓':'Encontra a bandeira'}else if(mode==='menu'){cam=200+Math.sin(clock*.1)*80}for(let i=particles.length-1;i>=0;i--){const q=particles[i];if(!paused){q.x+=q.vx*dt;q.y+=q.vy*dt;q.vy+=400*dt;q.life-=dt}if(q.life<=0)particles.splice(i,1)}if(clock>messageUntil)$('notice').classList.remove('show');c.setTransform(scale,0,0,scale,0,0);world()}requestAnimationFrame(frame);
